insert into public.knowledge_base_entries
  (slug, kind, title, summary, body_html, category, audiences, active, position, published_at)
select
  'emitir-nada-consta', 'article', 'Como emitir o Nada Consta',
  'Saiba quando solicitar o documento no Meu Pergamum e como enviá-lo ao Pronto!',
  '<section class="knowledge-card knowledge-card--warning"><h2><span class="knowledge-card__icon" aria-hidden="true">!</span>Antes de solicitar</h2><p>O Nada Consta comprova que você não tem pendências com as bibliotecas da UFBA, como livros, chaves ou outros materiais emprestados. Regularize qualquer pendência com a biblioteca antes de solicitar o documento.</p><p>A emissão encerra seu cadastro nas bibliotecas da UFBA. Depois disso, você não poderá fazer empréstimos ou solicitar outros serviços; a consulta local ao acervo e o uso do salão de leitura continuam disponíveis. Solicite o Nada Consta quando estiver concluindo o curso ou em caso de desligamento total.</p></section><section class="knowledge-card knowledge-card--info"><h2><span class="knowledge-card__icon" aria-hidden="true">☁</span>Emita no Meu Pergamum</h2><ol class="knowledge-steps"><li><p>Acesse o Meu Pergamum da UFBA com suas credenciais.</p></li><li><p>Solicite a emissão do Nada Consta. Se houver pendências ou não conseguir emitir o documento, procure a biblioteca para regularizar sua situação.</p></li><li><p>Salve o Nada Consta emitido em PDF.</p></li></ol><p class="knowledge-card__link"><a href="https://arquitetura.ufba.br/sites/arquitetura.ufba.br/files/guia-emissao-nada-consta-bibfaufba-2025.pdf">Consulte o guia oficial de emissão da BIB/FA</a></p></section><section class="knowledge-card knowledge-card--allowed"><h2><span class="knowledge-card__icon" aria-hidden="true">✓</span>Envie ao Pronto!</h2><ol class="knowledge-steps"><li><p>Volte à sua solicitação no painel do Pronto!.</p></li><li><p>Na área Envio do Nada Consta, escolha o PDF de até 5 MB e clique em Enviar Nada Consta.</p></li><li><p>Acompanhe a conferência do documento pela biblioteca no painel.</p></li></ol></section>',
  'Solicitação', array['public','student','panel'], true, 1070, now()
where not exists (select 1 from public.knowledge_base_entries where slug = 'emitir-nada-consta');
